select oo.id, ood.id as detailId, oo.code, oo.type, oo.out_type as outType, ooc.name as customerName, oo.inventory_direction as inventoryDirection, oo.approve_status as approveStatus, oo.invalid_status as invalidStatus, ood.sku_id as skuId, ood.sku_no as skuNo, oo.bill_date as billDate, ood.actual_qty as actualQty, ood.unit, oo.warehouse_name as warehouseName, ood.warehouse_location as warehouseLocation, oo.process_apply_code as processApplyCode, oo.approve_user_name as approveUserName, oo.approve_time as approveTime, oo.create_user_name as createUserName, oo.create_time as createTime, oo.source_code as sourceCode from other_outstock oo inner join other_outstock_customer ooc on oo.id = ooc.main_id and ooc.is_deleted = false inner join other_outstock_detail ood on oo.id = ood.main_id and ood.is_deleted = false
${params.sqlMap.default} and oo.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
oo.id desc,ood.id asc

