        and oo.bill_date >= #{params.billDateList[0]} and  (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > oo.bill_date


        ${params.permissionSql}

select oo.id, ood.id as detailId, oo.code, oo.type, oo.out_type as outType, ooc.name as customerName, oo.inventory_direction as inventoryDirection, oo.approve_status as approveStatus, oo.invalid_status as invalidStatus, ood.sku_id as skuId, ood.sku_no as skuNo, oo.bill_date as billDate, ood.actual_qty as actualQty, ood.unit, oo.warehouse_name as warehouseName, ood.warehouse_location as warehouseLocation, oo.process_apply_code as processApplyCode, oo.approve_user_name as approveUserName, oo.approve_time as approveTime, oo.create_user_name as createUserName, oo.create_time as createTime, oo.source_code as sourceCode from other_outstock oo inner join other_outstock_customer ooc on oo.id = ooc.main_id and ooc.is_deleted = false inner join other_outstock_detail ood on oo.id = ood.main_id and ood.is_deleted = false
${params.sqlMap.default} and oo.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
oo.id desc,ood.id asc

SELECT DISTINCT oo.id, oo.code, oo.approve_status, oo.warehouse_name, oo.create_time FROM other_outstock oo INNER JOIN other_outstock_detail ood on oo.id = ood.main_id AND ood.is_deleted = FALSE WHERE oo.is_deleted = FALSE AND oo.invalid_status = FALSE
and oo.approve_status in
#{item}
and oo.bill_date >= #{params.billDateList[0]} and (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > oo.bill_date
${params.permissionSql}
${item.field} ${item.sort}
ORDER BY oo.create_time desc

select oo.id, ood.id as detailId, oo.code, oo.type, oo.out_type as outType, ooc.name as customerName, oo.inventory_direction as inventoryDirection, oo.approve_status as approveStatus, oo.invalid_status as invalidStatus, ood.sku_id as skuId, ood.sku_no as skuNo, oo.bill_date as billDate, ood.actual_qty as actualQty, ood.unit, oo.warehouse_name as warehouseName, ood.warehouse_location as warehouseLocation, oo.process_apply_code as processApplyCode, oo.approve_user_name as approveUserName, oo.approve_time as approveTime, oo.create_user_name as createUserName, oo.create_time as createTime from other_outstock oo left join other_outstock_customer ooc on oo.id = ooc.main_id and ooc.is_deleted = false left join other_outstock_detail ood on oo.id = ood.main_id and ood.is_deleted = false
oo.is_deleted = false and oo.source_type = 'sampleRecipient'
and oo.source_id = #{params.id}
${params.permissionSql}
order by oo.create_time desc
